export const GPSS_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/gpss-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getGpssStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(GPSS_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
